import{_ as e,o,c as r,ag as a}from"./chunks/framework.BJFNwp4n.js";const d="/images/open-source/kafka/message-flow.zh.svg",f=JSON.parse('{"title":"Kafka 核心模型与选型","description":"Kafka 的核心模型与选型：一条消息的完整链路、集群与分区概念、副本角色、日志存储与 acks 写入确认、核心能力、典型场景、性能量级与同类中间件对比。","frontmatter":{"description":"Kafka 的核心模型与选型：一条消息的完整链路、集群与分区概念、副本角色、日志存储与 acks 写入确认、核心能力、典型场景、性能量级与同类中间件对比。","date":"2026-11-12T00:00:00.000Z","recommend":2,"tag":["Kafka"],"tags":["Kafka","Docker","KRaft"],"categories":["Open Source"]},"headers":[],"relativePath":"zh/open-source/kafka/introduction.md","filePath":"zh/open-source/kafka/introduction.md"}'),i={name:"zh/open-source/kafka/introduction.md"};function n(l,t,c,s,h,k){return o(),r("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1794441600000"},[...t[0]||(t[0]=[a('<h1 id="kafka-核心模型与选型" tabindex="-1">Kafka 核心模型与选型 <a class="header-anchor" href="#kafka-核心模型与选型" aria-label="Permalink to &quot;Kafka 核心模型与选型&quot;">​</a></h1><p>Kafka 是一个分布式提交日志：消息只追加到磁盘日志的末尾，多个消费者各自按自己的进度读取同一份数据。它面向高吞吐的事件流场景，而不是逐条投递、读走即删的任务队列。</p><p>一条消息的路径贯穿全链路：Producer 选定分区并写入该分区的 Leader 副本，Follower 持续同步形成 ISR，属于某个 Consumer Group 的消费者再按位点拉取。配套代码与启动脚本在仓库 <a href="https://github.com/zq-xu/zq-xu.github.io/tree/master/docs/public/demos/kafka" target="_blank" rel="noreferrer"><code>docs/public/demos/kafka</code></a>。</p><h2 id="kafka-是什么" tabindex="-1">Kafka 是什么 <a class="header-anchor" href="#kafka-是什么" aria-label="Permalink to &quot;Kafka 是什么&quot;">​</a></h2><p>概括地说：<strong>Kafka 是把消息顺序写进磁盘、并允许很多消费者各自按进度去读的分布式提交日志。</strong></p><p>理解这句话的三个关键词：</p><ul><li><strong>顺序写</strong>：消息只会追加到日志末尾，磁盘顺序写的吞吐远高于随机写；</li><li><strong>不投递即删</strong>：消息按保留策略（时间或大小）删除，不是被谁读走就消失，所以同一份数据可以被反复回放；</li><li><strong>各自按进度读</strong>：每个消费者只维护自己的位点（offset），互不干扰，读多读少都不影响别人。</li></ul><p>这三点决定了它的定位：<strong>高吞吐的事件流平台</strong>，而不是任务派发队列。</p><h2 id="一条消息的完整链路" tabindex="-1">一条消息的完整链路 <a class="header-anchor" href="#一条消息的完整链路" aria-label="Permalink to &quot;一条消息的完整链路&quot;">​</a></h2><img class="kafka-flow" src="'+d+'" alt="消息从生产到消费的全链路：Producer → Broker 内的 Topic / Partition → Consumer Group，位点写回 __consumer_offsets"><p>上图把 Kafka 拆成三层：<strong>客户端（Producer / Consumer）</strong>、<strong>Broker 内的存储（Topic / Partition / Replica）</strong>、<strong>位点存储（<code>__consumer_offsets</code>）</strong>。图中的 ①～③ 就是一条消息的完整生命线，下面按这个顺序展开。</p><blockquote><p>图里为了简洁只画了一个 Broker。实际每个 Partition 的副本会分布在多台 Broker 上；图中的 Leader 指“这个分区自己的 Leader”，不是某一台 Broker 的身份，后文会专门说明。</p></blockquote><ol><li><strong>Producer 决定写到哪个分区</strong>：带 key 时按 <code>hash(key) % 分区数</code> 固定落点，不带 key 时轮询或粘性分配。选分区这一步，决定了这条消息和谁排在同一队里。</li><li><strong>写入分区的 Leader</strong>：Producer 只写 Leader 副本；Broker 把消息追加到该分区日志末尾，并返回这条消息的 offset。<code>acks=all</code> 时还要等 ISR（In-Sync Replicas，同步副本集合）全部落盘才返回（见后文“写入确认：acks 的三个级别”）。</li><li><strong>Follower 同步，形成 ISR</strong>：Follower 持续从 Leader 拉取新消息；跟得上进度的副本留在 ISR 里，跟不上的会被踢出。Leader 故障时，从 ISR 中选新 Leader。</li><li><strong>消息在分区内获得 offset</strong>：offset 是分区内的“行号”，严格递增；跨分区之间没有顺序。</li><li><strong>Consumer 按位点拉取</strong>：Consumer 属于某个 Consumer Group，组内把 Partition 分给成员——<strong>一个 Partition 同一时刻只属于一个成员</strong>；不同组之间互不影响。</li><li><strong>提交位点</strong>：处理完把“下一条要读的 offset”写进 <code>__consumer_offsets</code>。位点和消息分开存储，所以回拨位点就能重放历史。</li><li><strong>保留策略删除旧数据</strong>：到期的日志段（segment，日志按大小或时间切出的段文件）被整段删除，但位点不会自动重置；按已删除的位点读会得到“越界”错误。</li></ol><blockquote><p>整条链路里只有第 2 步在“写”，其余都在读同一份日志的不同位置。这正是 Kafka 与“读走即删”的队列最本质的区别。</p></blockquote><h2 id="概念总览" tabindex="-1">概念总览 <a class="header-anchor" href="#概念总览" aria-label="Permalink to &quot;概念总览&quot;">​</a></h2><p>Kafka 的概念不是并列的名词，而是一条从集群到分区的包含链。下面按存储、生产者、消费者三部分展开；副本角色、日志格式与写入确认见“副本、日志与写入确认”。</p><h3 id="集群与存储" tabindex="-1">集群与存储 <a class="header-anchor" href="#集群与存储" aria-label="Permalink to &quot;集群与存储&quot;">​</a></h3><p>从大到小的包含关系是：</p><p><strong>Cluster → Broker（其中一台兼任 Controller）→ Topic → Partition → Replica</strong>；<strong>Offset</strong> 是 Partition 内的位置，<strong>Consumer Group</strong> 是消费侧的分配单位，<strong><code>__consumer_offsets</code></strong> 记录每个组的读进度。</p><p>集群层有两个角色：<strong>Broker</strong> 是存数据的服务节点；<strong>Controller</strong> 负责维护元数据（有哪些 Topic、每个分区的副本放在哪台 Broker、谁是 Leader），并决定分区 Leader 的选举。</p><p>Kafka 早期把这些元数据交给外部的 ZooKeeper 管理；从 3.x 起改为内置的 <strong>KRaft（Kafka Raft）</strong>——用 Raft 共识在 Kafka 内部选出 Controller，由它管理元数据和副本分配，不再依赖 ZooKeeper。本机的单节点集群就是 KRaft 模式，那台 Broker 同时兼任 Controller。</p><table tabindex="0"><thead><tr><th>概念</th><th>层级</th><th>定义</th><th>与其他概念的关系</th></tr></thead><tbody><tr><td>Broker</td><td>集群</td><td>一个 Kafka 服务节点</td><td>一个集群由多台 Broker 组成；每台持有若干 Partition 的副本</td></tr><tr><td>Controller</td><td>集群</td><td>负责元数据、分区分配与 Leader 选举，由某台 Broker 兼任</td><td><strong>不是 Partition 的 Leader</strong>；一个集群同一时刻只有一个 active controller</td></tr><tr><td>Topic</td><td>Topic</td><td>消息的逻辑分类，类似表名</td><td>固定包含 N 个 Partition，N 在创建 Topic 时确定；Topic 本身没有 Leader</td></tr><tr><td>Partition</td><td>Partition</td><td>Topic 的分片，一份只追加的日志</td><td>并行与有序的最小单位；每个 Partition 在集群内有多份 Replica</td></tr><tr><td>Replica</td><td>Partition</td><td>某个 Partition 的一份拷贝，放在某台 Broker 上</td><td>副本数由 <code>replication.factor</code> 决定（配置在 Topic 上，但<strong>每个 Partition 各自拥有一组副本</strong>）</td></tr><tr><td>Offset</td><td>Partition</td><td>消息在某个 Partition 内的递增编号</td><td>只在所属 Partition 内有意义；Consumer 提交的位点也是 offset</td></tr></tbody></table><h3 id="生产者" tabindex="-1">生产者 <a class="header-anchor" href="#生产者" aria-label="Permalink to &quot;生产者&quot;">​</a></h3><p>Producer 是写客户端，负责选分区、攒批、压缩、重试与幂等。它只把消息发给目标分区的 Leader；Leader 与 Follower 的分工在“关键机制”里说明。</p><ul><li><strong>选分区</strong>：带 key 时按 <code>hash(key) % 分区数</code> 计算落点；不带 key 时轮询或粘性分配，尽量把一批消息留在同一分区。</li><li><strong>批量与压缩</strong>：<code>batch.size</code>、<code>linger.ms</code> 决定攒批的大小与等待时间；压缩在客户端完成（<code>compression.type</code>），Broker 原样存储。</li><li><strong>写入确认</strong>：<code>acks</code> 决定等几个副本确认后才返回，取值与取舍见后文。</li><li><strong>重试与幂等</strong>：失败重试可能产生重复消息；开启幂等（<code>enable.idempotence=true</code>）后，Broker 会按生产者 ID 与序列号去重。</li></ul><h3 id="消费者与消费组" tabindex="-1">消费者与消费组 <a class="header-anchor" href="#消费者与消费组" aria-label="Permalink to &quot;消费者与消费组&quot;">​</a></h3><p>Consumer 是读客户端，按位点拉取并处理消息。多个 Consumer 可以组成 Consumer Group，共同订阅同一个 Topic。</p><table tabindex="0"><thead><tr><th>概念</th><th>定义</th><th>与其他概念的关系</th></tr></thead><tbody><tr><td>Consumer</td><td>读客户端：按位点拉取并处理</td><td>必须属于一个 Consumer Group；可手动或自动提交位点</td></tr><tr><td>Consumer Group</td><td>同一份订阅的消费组</td><td>组内 Partition 独占分配；组间各自独立、互不影响</td></tr><tr><td>Group Coordinator</td><td>Broker 侧管理组与 rebalance 的组件</td><td>组成员变化时触发 Rebalance，期间消费暂停</td></tr><tr><td>Rebalance</td><td>分区在组内重新分配</td><td>成员加入 / 离开 / 订阅变化时发生</td></tr><tr><td><code>__consumer_offsets</code></td><td>存位点的内部 Topic</td><td>按 (group, topic, partition) 记录“下一条要读”的 offset</td></tr></tbody></table><p>同一个 Group 内，一个 Partition 同一时刻只分给一个成员；不同 Group 各自维护位点，所以同一份日志可以被多个组按不同进度读。</p><h3 id="几个容易混淆的边界" tabindex="-1">几个容易混淆的边界 <a class="header-anchor" href="#几个容易混淆的边界" aria-label="Permalink to &quot;几个容易混淆的边界&quot;">​</a></h3><ul><li><strong>有序边界</strong>：只在 Partition 内有序；只有同一 key 才保证落同一 Partition。</li><li><strong>并行边界</strong>：一个 Consumer Group 的并行度上限 = 订阅 Topic 的 Partition 数；多出来的 Consumer 只能空转（可做热备）。</li><li><strong>确认边界</strong>：Kafka 确认的是“位点”，不是“单条消息 ack”；重复消费要靠幂等生产或事务来兜底。</li><li><strong>分区数量边界</strong>：分区数只能增加，不能减少；扩容会改变 key 的落点，历史消息不会重排。</li></ul><h2 id="副本、日志与写入确认" tabindex="-1">副本、日志与写入确认 <a class="header-anchor" href="#副本、日志与写入确认" aria-label="Permalink to &quot;副本、日志与写入确认&quot;">​</a></h2><h3 id="leader-与-follower-分区副本角色" tabindex="-1">Leader 与 Follower：分区副本角色 <a class="header-anchor" href="#leader-与-follower-分区副本角色" aria-label="Permalink to &quot;Leader 与 Follower：分区副本角色&quot;">​</a></h3><p>结论先行：<strong>Leader / Follower 是“每个 Partition 自己的副本角色”，既不属于整个集群，也不属于 Topic。</strong></p><ul><li>Topic 只是分区的集合，本身没有 Leader；<code>replication.factor</code> 虽然配在 Topic 上，但作用对象是该 Topic 的每个 Partition。</li><li>一个 Partition 的副本会分散到多台 Broker，其中一份选为 Leader，其余为 Follower；<strong>每个 Partition 独立选自己的 Leader</strong>。</li><li>因此同一台 Broker 往往同时是某些 Partition 的 Leader、另一些 Partition 的 Follower。</li><li>与该 Partition 的 Leader 保持同步的副本集合称为 <strong>ISR（In-Sync Replicas）</strong>；Leader 故障时从 ISR 中选新 Leader，<code>acks=all</code> 会等 ISR 确认。</li><li>集群层面另有一个 Controller，负责元数据与 Leader 选举；它和 Partition Leader 是两个不同概念。</li></ul><p>以 3 台 Broker、1 个 3 分区、<code>replication.factor=3</code> 的 Topic 为例：</p><table tabindex="0"><thead><tr><th>Partition</th><th>Leader</th><th>Follower</th><th>ISR</th></tr></thead><tbody><tr><td>P0</td><td>Broker 1</td><td>Broker 2, Broker 3</td><td>Broker 1, 2, 3</td></tr><tr><td>P1</td><td>Broker 2</td><td>Broker 1, Broker 3</td><td>Broker 1, 2, 3</td></tr><tr><td>P2</td><td>Broker 3</td><td>Broker 1, Broker 2</td><td>Broker 1, 2, 3</td></tr></tbody></table><p>写 P0 时，Producer 只连 Broker 1；Broker 2、3 作为 Follower 同步。Broker 1 同时还是 P1、P2 的 Follower，但这不影响它作为 P0 Leader 的读写。</p><h3 id="日志存储-segment、retention-与-compact" tabindex="-1">日志存储：Segment、Retention 与 Compact <a class="header-anchor" href="#日志存储-segment、retention-与-compact" aria-label="Permalink to &quot;日志存储：Segment、Retention 与 Compact&quot;">​</a></h3><p>Partition 在磁盘上是一个目录，日志不是一个无限增长的大文件，而是被切成多个 <strong>segment</strong>：</p><ul><li>新消息只追加到当前的 active segment（正在写入的那一段）；</li><li>当前段达到 <code>segment.bytes</code>（默认 1GB）或 <code>segment.ms</code>（默认 7 天）就封口，再开一个新段；</li><li>删除的最小单位是<strong>整个段</strong>。<code>retention.ms</code> / <code>retention.bytes</code> 到期后，旧段被整段删掉，不会去删段里的某几条。</li></ul><p>所以 retention 的效果是“旧数据消失”，不是“offset 归零”：offset 是逻辑位置，不会回退；读一个已经被删掉的 offset，会得到 out-of-range 错误。</p><p>旧段具体怎么处理，由 Topic 的 <code>cleanup.policy</code> 决定，只有两种取值：</p><table tabindex="0"><thead><tr><th>策略</th><th>行为</th><th>适合的场景</th></tr></thead><tbody><tr><td><code>delete</code>（默认）</td><td>按时间或大小删掉整个旧段</td><td>普通事件流、日志采集</td></tr><tr><td><code>compact</code></td><td>不按时间删，而是对每个 key 只保留最新一条记录</td><td>状态快照、changelog、配置同步</td></tr></tbody></table><p><code>compact</code> 不是 gzip / snappy 那种压缩算法，而是“按 key 折叠历史”。例如同一个 key 写入了三次：</p><table tabindex="0"><thead><tr><th>offset</th><th>key</th><th>value</th></tr></thead><tbody><tr><td>0</td><td><code>user-1</code></td><td><code>v1</code></td></tr><tr><td>5</td><td><code>user-1</code></td><td><code>v2</code></td></tr><tr><td>9</td><td><code>user-1</code></td><td><code>v3</code></td></tr></tbody></table><p>compact 生效后，每个 key 最终只剩一条，上例只保留 offset 9 的 <code>v3</code>；offset 0 和 5 被清理，但 offset 9 不变，因此日志里会出现 offset 空洞。要删除某个 key，写一条 value 为 <code>null</code> 的记录（tombstone，墓碑），超过 <code>delete.retention.ms</code> 后连墓碑也会被清掉。</p><p>这也解释了 compact 的用途：每个 key 只保留最新状态，消费者从头重放就能重建当前状态，所以它适合 changelog 和状态类 Topic。</p><h3 id="写入确认-acks-的三个级别" tabindex="-1">写入确认：acks 的三个级别 <a class="header-anchor" href="#写入确认-acks-的三个级别" aria-label="Permalink to &quot;写入确认：acks 的三个级别&quot;">​</a></h3><p><code>acks</code>（acknowledgement，确认）是 <strong>Producer 的参数</strong>，决定“一条消息要等到谁确认，才算写成功”。</p><table tabindex="0"><thead><tr><th>取值</th><th>等谁确认</th><th>代价与风险</th><th>适合的场景</th></tr></thead><tbody><tr><td><code>0</code></td><td>谁都不等，发出即成功</td><td>延迟最低、吞吐最高；但可能丢消息：Broker 没收到或网络断了，Producer 都不知道</td><td>日志、指标等允许丢数据的场景</td></tr><tr><td><code>1</code></td><td>等 Leader 写进本地日志</td><td>延迟中等；Leader 确认后、Follower 同步前宕机，新 Leader 可能没有这条消息</td><td>一般业务，能容忍极少量丢失</td></tr><tr><td><code>all</code>（也可写 <code>-1</code>）</td><td>等 ISR 里所有副本写入</td><td>延迟最高、吞吐最低；只要 ISR 足够，已确认的消息就不会丢</td><td>订单、支付、状态变更</td></tr></tbody></table><p>几个容易混淆的点：</p><ul><li><code>acks</code> 配在 Producer 上；<code>min.insync.replicas</code> 配在 Broker / Topic 上，两者配合才决定“最少几份副本”。例如 <code>acks=all</code> + <code>min.insync.replicas=2</code>：ISR 少于 2 个副本时，写入直接失败（<code>NotEnoughReplicas</code>），而不是悄悄只写 Leader。</li><li>Kafka 3.x 的 Producer 默认就是 <code>acks=all</code>；改成 <code>0</code> / <code>1</code> 属于显式用可靠性换吞吐。</li><li>幂等生产（idempotence）要求 <code>acks=all</code>；<code>acks=0/1</code> 下重试可能产生重复消息。</li><li><code>acks</code> 只覆盖“写到副本”这一段，不保证消费端只处理一次；端到端精确一次要靠事务或幂等消费。</li></ul><h2 id="核心能力" tabindex="-1">核心能力 <a class="header-anchor" href="#核心能力" aria-label="Permalink to &quot;核心能力&quot;">​</a></h2><ul><li><strong>读写与持久化</strong>：发布订阅、按 <code>retention.ms</code> 回放、日志清理策略 compact（按 key 保留最新）</li><li><strong>并行与容错</strong>：分区并行、副本与 ISR、消费组与自动 rebalance</li><li><strong>有序与可靠</strong>：分区内有序、幂等生产、事务</li><li><strong>生态与治理</strong>：压缩（gzip / snappy / lz4 / zstd）、Kafka Connect、Kafka Streams、配额与多租户</li></ul><h2 id="典型应用场景" tabindex="-1">典型应用场景 <a class="header-anchor" href="#典型应用场景" aria-label="Permalink to &quot;典型应用场景&quot;">​</a></h2><ul><li>日志与指标采集</li><li>用户行为埋点</li><li>CDC（Change Data Capture，变更数据捕获）：binlog → Kafka → 缓存 / 搜索 / 数仓</li><li>事件驱动微服务</li><li>流计算入口（Flink / Kafka Streams）</li><li>削峰填谷、历史数据回放</li><li>事件溯源与审计</li></ul><h2 id="性能量级" tabindex="-1">性能量级 <a class="header-anchor" href="#性能量级" aria-label="Permalink to &quot;性能量级&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指标</th><th>量级</th><th>影响因素</th></tr></thead><tbody><tr><td>单 broker 写入</td><td>小消息数十万~百万条/秒，百 MB/s 级</td><td>消息大小、批量、压缩、<code>acks</code>、磁盘顺序写</td></tr><tr><td>单 broker 读取</td><td>与写入同量级或更高</td><td>页缓存、拉取批量、解压开销</td></tr><tr><td>延迟</td><td><code>acks=0</code> 亚毫秒；<code>acks=1</code> 1~3ms；<code>acks=all</code> 同机房几 ms</td><td>acks、副本数、跨机房 RTT（round-trip time，网络往返时延）</td></tr><tr><td>单分区</td><td>常见 10MB/s 级</td><td>单分区是顺序瓶颈，靠多分区扩展</td></tr><tr><td>保留</td><td>TB ~ PB</td><td>磁盘容量 + 保留策略 + 压缩比</td></tr></tbody></table><blockquote><p>表中 MB/s、GB、TB、PB 均为吞吐与容量单位（1 PB = 1024 TB）。</p></blockquote><p>公开案例量级：LinkedIn 曾公开日均数万亿条消息，Netflix、Uber 也在每秒数百万事件的规模上使用。</p><p>本机实测（单机 Docker、单进程 Go 客户端、小消息、<code>acks=all</code> + 幂等）：</p><table tabindex="0"><thead><tr><th>方式</th><th>结果</th></tr></thead><tbody><tr><td>同步生产（逐条等 ACK，acknowledgement 确认）</td><td>9~12 条 / 19~29ms ≈ <strong>400 条/秒</strong></td></tr><tr><td>异步生产（批量攒包）</td><td>200 条 / 15ms ≈ <strong>13000 条/秒</strong></td></tr></tbody></table><p>差 30 倍全部来自“是否逐条等一个网络往返”。吞吐不够时，先看客户端是不是在同步逐条发。</p><h2 id="选型建议" tabindex="-1">选型建议 <a class="header-anchor" href="#选型建议" aria-label="Permalink to &quot;选型建议&quot;">​</a></h2><p><strong>适合</strong>：高吞吐事件流且要落盘可回放；多个下游各自按不同速度消费同一份数据； 需要按 key 有序；要做流处理入口或 CDC；能接受最终一致 + 异步。</p><p><strong>不太适合</strong>：</p><table tabindex="0"><thead><tr><th>场景</th><th>更合适</th><th>原因</th></tr></thead><tbody><tr><td>复杂路由、延迟队列、优先级队列</td><td>RabbitMQ</td><td>Kafka 没有 per-message 路由与优先级</td></tr><tr><td>单机轻量、只要“能用的队列”</td><td>Redis Stream / RabbitMQ</td><td>Kafka 组件多、调参多</td></tr><tr><td>任务派发（单条确认与重试）</td><td>RabbitMQ / SQS（Amazon Simple Queue Service，AWS 托管队列）</td><td>Kafka 的确认粒度是分区位点</td></tr><tr><td>超大多租户 + 分层存储</td><td>Pulsar</td><td>Kafka 需额外组件</td></tr><tr><td>服务间同步调用</td><td>gRPC / HTTP</td><td>中间件只会加延迟</td></tr><tr><td>数据量很小（每天几万条）</td><td>数据库表 / 定时任务</td><td>运维成本远大于收益</td></tr></tbody></table><p>选型可归纳为：<strong>日志 / 事件流 + 高吞吐 + 可回放 → Kafka；任务分发 + 精细路由 + 低延迟确认 → RabbitMQ 类。</strong></p><p>本系列的本地实践使用 Kafka 3.9.1 官方镜像 <code>apache/kafka:3.9.1</code>，运行在 KRaft 模式下，集群的创建与验证见 <a href="./local-deployment.html">Kafka 本地部署与运行</a>。</p><h2 id="版本与参考" tabindex="-1">版本与参考 <a class="header-anchor" href="#版本与参考" aria-label="Permalink to &quot;版本与参考&quot;">​</a></h2><ul><li>本系列版本：Kafka <code>3.9.1</code>（KRaft 模式）、Go 客户端 sarama <code>v1.60.2</code>。</li><li><a href="https://kafka.apache.org/documentation/" target="_blank" rel="noreferrer">Apache Kafka 官方文档</a>：配置项、协议与运维手册的权威来源。</li><li><a href="https://kafka.apache.org/documentation/#kraft" target="_blank" rel="noreferrer">KRaft 模式说明</a>：不依赖 ZooKeeper 的元数据管理方式。</li><li><a href="https://kafka.apache.org/documentation/#configuration" target="_blank" rel="noreferrer">Kafka配置文档</a>：Broker、Topic 与客户端配置的完整列表。</li></ul>',72)])])}const g=e(i,[["render",n]]);export{f as __pageData,g as default};
